// Функция для расчёта среднего значения
function mean(arr) {
  const sum = arr.reduce((acc, val) => acc + val, 0);
  return sum / arr.length;
}

// Функция для расчёта стандартного отклонения
function stdDev(arr) {
  const avg = mean(arr);
  const squareDiffs = arr.map((val) => Math.pow(val - avg, 2));
  const avgSquareDiff = mean(squareDiffs);
  return Math.sqrt(avgSquareDiff);
}

// Функция для расчёта коэффициента Шарпа
export function calculateSharpeRatio(returns, riskFreeRate = 0) {
  if (returns.length === 0) return 0;

  const meanReturn = mean(returns);
  const risk = stdDev(returns);

  if (risk === 0) return Infinity; // Избегаем деления на ноль

  return (meanReturn - riskFreeRate) / risk;
}
