import { createSlice } from '@reduxjs/toolkit';

const initialState = {
  data: null,
  autofollow: false,
  isLoading: false,
};

export const userDataSlice = createSlice({
  name: 'userData',
  initialState,
  reducers: {
    fetchUserDataRequest: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    fetchUserDataSuccess: (state, action) => {
      state.isLoading = false;
      state.data = action.payload;
      state.autofollow = action.payload.autofollow || false;
      state.startTime = action.payload.startTime || null;
      state.error = null;
    },
    fetchUserDataFailure: (state, action) => {
      state.isLoading = false;
      state.error = action.payload;
    },
    saveAccountNumberRequest: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    saveAccountNumberSuccess: (state, action) => {
      state.isLoading = false;
      state.data = {
        ...state.data,
        ...action.payload, // обновляем данные (например, demoAccountNumber)
      };
    },
    saveAccountNumberFailure: (state, action) => {
      state.isLoading = false;
      state.error = action.payload;
    },
    autoTrackingRequest: (state) => {
      state.isLoading = true;
      state.error = null;
    },
    autoTrackingSuccess: (state, action) => {
      state.isLoading = false;
      state.autofollow = action.payload.autofollow;
      state.startTime = action.payload.startTime || null;
    },
    autoTrackingFailure: (state, action) => {
      state.isLoading = false;
      state.error = action.payload;
    },
  },
});

export const {
  fetchUserDataRequest,
  fetchUserDataSuccess,
  fetchUserDataFailure,
  saveAccountNumberRequest,
  saveAccountNumberSuccess,
  saveAccountNumberFailure,
  autoTrackingRequest,
  autoTrackingSuccess,
  autoTrackingFailure,
} = userDataSlice.actions;

export default userDataSlice.reducer;
