import { useEffect } from 'react';
import { BrowserRouter, Route, Routes, useLocation } from 'react-router-dom';
import { DashboardHeader } from './components/headers/DashboardHeader';
import { Home } from './pages/Home';
import { Trades } from './pages/Trades';
import { Login } from './components/user/Login';
import Register from './components/user/Register/Register';
import Blog from './components/blog/Blog';
import { AffiliateProgram } from './pages/AffiliateProgram';
import { DashboardFooter } from './components/footers/DashboardFooter';
import { Technologies } from './pages/Technologies';
import { Safety } from './pages/Safety';
import { Connect } from './pages/Connect';
import { RegularUser } from './components/user/profile/RegularUser/RegularUser';
import SuperUser from './components/user/profile/SuperUser';
import './index.css';
import { users } from './backend_data';
import { useDispatch, useSelector } from 'react-redux';
import { DevElementsProvider } from './components/development/DevElementsContext';
import StockBackground from './components/background/StockBackground';
import { Strategies } from './pages/Strategies/Strategies';
import { PrivateRoute } from './utils/PrivateRoute';
import { ToastContainer } from 'react-toastify';
import { logout, fetchLoginSuccess } from './redux/slices/loginSlice';
import { fetchUserDataApi } from './api/authApi';
import 'react-toastify/dist/ReactToastify.css';

function App() {
  const dispatch = useDispatch();

  useEffect(() => {
    const checkToken = async () => {
      const token = localStorage.getItem('token');
      const user = localStorage.getItem('user');
      if (token && user) {
        // Пробуем получить данные пользователя с этим токеном
        try {
          // Например, запрос к /user-data (или /me, если реализуешь)
          const { data, status } = await fetchUserDataApi(JSON.parse(user).id);
          if (status === 200) {
            // Всё ок, обновляем Redux (если нужно)
            dispatch(fetchLoginSuccess({ user: JSON.parse(user), token }));
          } else {
            // Токен невалиден или истёк
            dispatch(logout());
          }
        } catch (e) {
          dispatch(logout());
        }
      } else {
        dispatch(logout());
      }
    };

    checkToken();
  }, [dispatch]);

  return (
    <>
      {/*<StockBackground /> {/* Добавлен фон */}
      <BrowserRouter>
        <DashboardHeader />
        <Routes>
          {/* Главная страница с секциями */}
          <Route
            path="/"
            element={
              <div className="main-conteiner">
                {/* Полоса вверху экрана */}
                {/*<div className="top-line" />*/}
                <section id="home">
                  <Home />
                </section>
                <section id="trades">
                  <Trades />
                </section>
                <section id="strategies">
                  <Strategies />
                </section>
                <section id="technologies">
                  <Technologies />
                </section>
                <section id="safety">
                  <Safety />
                </section>
                <section id="сonnect">
                  <Connect />
                </section>
                <section id="affiliateProgram">
                  <AffiliateProgram />
                </section>
              </div>
            }
          />

          {/* Отдельные страницы */}
          {/*<Route
            path="/profile"
            element={
              logged_in_user["isSuperUser"] === 1 ? (
                <SuperUser />
              ) : (
                <RegularUser />
              )
            }
          />*/}
          <Route path="/login" element={<Login />} />
          <Route path="/register" element={<Register />} />
          <Route element={<PrivateRoute />}>
            <Route path="/profile" element={<RegularUser />} />
            {/* можно добавить и другие защищённые маршруты */}
          </Route>
        </Routes>

        <ToastContainer />
      </BrowserRouter>
    </>
  );
}

export default App;
