import { useEffect, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './Home.module.css';

// Контейнер
const containerVariants = {
  hidden: { opacity: 0 },
  visible: {
    opacity: 1,
    transition: {
      when: 'beforeChildren',
      staggerChildren: 0.25,
    },
  },
};

// FOR — влево
const logoTextFirstAnimation = {
  hidden: {
    x: '-20vw',
    opacity: 0,
  },
  visible: {
    x: '0vw',
    opacity: 1,
    transition: {
      type: 'spring',
      stiffness: 80,
      damping: 18,
      duration: 0.6,
    },
  },
};

// WARD — вправо
const logoTextSecondAnimation = {
  hidden: {
    x: '70vw',
    opacity: 0,
  },
  visible: {
    x: '31.37vw',
    opacity: 1,
    transition: {
      type: 'spring',
      stiffness: 85,
      damping: 20,
      duration: 0.6,
      delay: 0.2,
    },
  },
};

// TRADING — снизу вверх
const logoTextThirdAnimation = {
  hidden: {
    y: '45vw',
    opacity: 0,
  },
  visible: {
    y: '-24.0vw',
    opacity: 1,
    transition: {
      type: 'spring',
      stiffness: 90,
      damping: 16,
      delay: 0.6,
    },
  },
};

// Description блок
const descriptionAnimation = {
  hidden: {
    opacity: 0,
    y: '10vw',
  },
  visible: {
    opacity: 1,
    y: '-21.5vw',
    transition: {
      type: 'tween',
      duration: 0.7,
      delay: 0.9,
    },
  },
};

export const Home = () => {
  const navigate = useNavigate();
  const buttonRef = useRef(null);
  const [isSticky, setIsSticky] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      if (!buttonRef.current) return;
      const rect = buttonRef.current.getBoundingClientRect();
      if (rect.top <= 20 && !isSticky) setIsSticky(true);
      if (window.scrollY < buttonRef.current.offsetTop && isSticky) setIsSticky(false);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isSticky]);

  return (
    <AnimatePresence>
      <motion.div
        className={styles.container}
        variants={containerVariants}
        initial="hidden"
        animate="visible"
        exit="hidden"
      >
        <div className={styles.logoBlock}>
          <motion.h1 variants={logoTextFirstAnimation} className={styles.logoTextFirst}>
            FOR
          </motion.h1>

          <motion.h1
            variants={logoTextSecondAnimation}
            className={styles.logoTextSecond}
            style={{ y: '-12vw' }}
          >
            WARD
          </motion.h1>
        </div>

        <motion.div className={styles.descriptionBlock} variants={descriptionAnimation}>
          <h3 className={styles.descriptionTitle}>
            МЫ УВАЖАЕМ ВАШЕ ВРЕМЯ
            <br />
            И ГОТОВЫ ВЗЯТЬ НА СЕБЯ
            <br />
            ЧАСТЬ ЗАБОТ
            <br />
            ПО ДИВЕРСИФИКАЦИИ <br />
            ВАШЕГО ДЕПОЗИТА
          </h3>

          <h3 className={styles.descriptionSubtitle}>ТОРГОВЛЯ БУДУЩЕГО. СЕГОДНЯ</h3>
        </motion.div>
        <motion.h1 variants={logoTextThirdAnimation} className={styles.logoTextThird}>
          TRADING
        </motion.h1>
      </motion.div>
    </AnimatePresence>
  );
};
