import React, { useState, useEffect, useRef } from 'react';
import { useSelector, useDispatch } from 'react-redux';
import { logout } from '../../../redux/slices/loginSlice';
import { Link as ScrollLink } from 'react-scroll';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import styles from './DashboardHeader.module.css';

const investButtonVariants = {
  hidden: {
    opacity: 0,
  },
  visible: {
    opacity: 1,
    transition: {
      delay: 1.6, // Задержка появления
      duration: 1.2, // Длительность проявления
      ease: 'easeInOut', // Плавное проявление
    },
  },
  exit: {
    opacity: 0,
    transition: {
      duration: 0.3,
      ease: 'easeInOut',
    },
  },
};

export const DashboardHeader = () => {
  const isAuthenticated = useSelector((state) => state.login.isAuthenticated);
  const user = useSelector((state) => state.login.user);
  const location = useLocation();
  const navigate = useNavigate();
  const dispatch = useDispatch();

  const isHomePage = location.pathname === '/';

  const [scrollTo, setScrollTo] = useState(null);
  const [activeSection, setActiveSection] = useState('home');
  const isHomeActive = activeSection === 'home';

  useEffect(() => {
    if (!isHomePage) return;

    const handleScroll = () => {
      const sectionIds = menuItemList.map((item) => item.link);
      for (let id of sectionIds) {
        const section = document.getElementById(id);
        if (section) {
          const top = section.getBoundingClientRect().top;
          if (top >= 0 && top <= window.innerHeight / 2) {
            setActiveSection(id);
            break;
          }
        }
      }
    };

    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, [isHomePage]);
  /* Список пунктов меню и их свойств. Думаю корректнее перенести на бэкэнд. */
  const menuItemList = [
    /*{
      name: "домой",
      link: "home",
      iconClass: styles.navLink,
      visible: true,
    },*/
    {
      name: 'трейды',
      link: 'trades',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'стратегии',
      link: 'strategies',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'технологии',
      link: 'technologies',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'безопасность',
      link: 'safety',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'начать работу',
      link: 'сonnect',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      name: 'партнерская программа',
      link: 'affiliateProgram',
      iconClass: styles.navLink,
      visible: true,
    },
    {
      /*
      name: "инвестировать",
      link: "/login",
      iconClass: styles.navLink,
      visible: true,
      isExternal: true*/
    },
  ];

  // Показывать кнопку только на определённом маршруте
  const showButton = location.pathname === '/';

  // Обработчик выхода
  const handleLogout = () => {
    if (isAuthenticated) {
      dispatch(logout());
    }
  };

  // Обработчик выбора пункта меню
  const handleMenuItemClick = (sectionId) => {
    if (sectionId === 'home') {

      setActiveSection('home');
      setScrollTo('home');
      navigate('/');
      return
    }
    if (location.pathname !== '/') {
      setScrollTo(sectionId);

      navigate('/');
    }
  };

  const handleLoginClick = () => {
    navigate('/login');
  };

  const [isSticky, setIsSticky] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setIsSticky(window.scrollY >= 475);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  return (
    <>
      <div className={`${styles.header} ${isHomePage ? styles.mainClor : ''}`}>
        <div className={`${styles.container}`}>
          <ScrollLink onClick={() => handleMenuItemClick('home')} to={'home'}>
            <div className={`${styles.companyIdentity} ${isHomeActive ? styles.brandActive : ''}`}>
              <div className={styles.logo}>
                <img src="/logo.svg" alt="logo" />
              </div>
              <span className={styles.brandName}>AITrading</span>
            </div>
          </ScrollLink>
          {isAuthenticated ? (
            <div className={styles.userInformation}>
              <div className={styles.userPhoto}>
                <img src="/icon/userPhoto.svg" alt="userPhoto" />
              </div>
              <h3 className={styles.userName}>{user.name}</h3>
            </div>
          ) : showButton ? (
            <button className={styles.loginButton} onClick={handleLoginClick}>
              кабинет
            </button>
          ) : null}
        </div>
        <div className={styles.mainMenu}>
          {/* Меню навигации */}
          <nav className={styles.navigation}>
            <div style={{ position: 'relative', display: 'flex' }}>
              <AnimatePresence>
                {menuItemList
                  .filter((item) => item.visible)
                  .map((item) => {
                    const isActive = item.link === activeSection;
                    console.log('activeSection', activeSection);
                    return !user ? (
                      <ScrollLink
                        key={item.name}
                        className={styles.navLink}
                        onClick={() => handleMenuItemClick(item.link)}
                        to={item.link}
                        smooth
                        offset={-130}
                        duration={0}
                      >
                        <div style={{ position: 'relative' }}>
                          <motion.span
                            animate={{ color: isActive ? '#ffc62e' : '#147aff' }}
                            transition={{ duration: 0.3 }}
                          >
                            {item.name}
                          </motion.span>

                          {isActive && (
                            <motion.div
                              layoutId="underline"
                              className={styles.underline}
                              initial={false}
                              animate={{ opacity: 1 }}
                              exit={{ opacity: 0 }}
                              transition={{ duration: 0.3 }}
                            />
                          )}
                        </div>
                      </ScrollLink>
                    ) : null;
                  })}
              </AnimatePresence>
            </div>
          </nav>
          {isAuthenticated ? (
            <>
              {/* Кнопка выхода */}
              <button className={styles.logoutButton} onClick={handleLogout}>
                выйти
              </button>{' '}
              {/* временное заменю на компонент */}
            </>
          ) : null}
        </div>
      </div>
      <AnimatePresence>
        {showButton && (
          <motion.button
            className={isSticky ? styles.stickyInvestButton : styles.investButton}
            onClick={handleLoginClick}
            variants={investButtonVariants}
            initial="hidden"
            animate="visible"
            exit="exit"
          >
            Инвестировать
          </motion.button>
        )}
      </AnimatePresence>
    </>
  );
};
