import React, { useState }  from 'react'
import { Efficiency } from '../Efficiency'
import { AutoTracking } from '../AutoTracking/AutoTracking';
import { useSelector } from 'react-redux';
import { calculateSharpeRatio } from '../../../../../utils/utils'; 

import styles from './Deposit.module.css'
import altStyles from './DepositAlt.module.css';

export const Deposit = ({statistics, real, showDepositCurrency = true, autoTrackingVisibility, cssVariant}) => {
  const isVisible = autoTrackingVisibility ?? true;
  const appliedStyles = cssVariant === 'alt' ? altStyles : styles;
  const [activeProfit, setActiveProfit] = useState('today'); // 'today' или 'total'
  const [isAutoTrackingEnabled, setIsAutoTrackingEnabled] = useState(false);
  const userData = useSelector((state) => state.userData?.data);
  const positionsOpenedNumber = userData?.accountInfo?.positions_opened?.length || 0;
  const positionsClosedNumber = userData?.accountInfo?.positions_closed?.length || 0;
  const tradesNumber = positionsOpenedNumber + positionsClosedNumber;

  const equity = userData?.accountInfo?.equity ?? 0;
  const margin = userData?.accountInfo?.margin ?? 0;

  const marginUsedPercent = (equity > 0 && margin > 0)
    ? (margin / equity * 100).toFixed(2)
    : '0';


  function calculateTotalProfit(accountInfo) {
  const closedProfit = accountInfo?.positions_closed?.reduce((sum, deal) => {
    return sum + Number(deal.profit || 0);
  }, 0) || 0;

  const openProfit = accountInfo?.positions_opened?.reduce((sum, deal) => {
    return sum + Number(deal.profit || 0);
  }, 0) || 0;

  const total = closedProfit + openProfit;

  return {
    totalProfit: Number(total.toFixed(2)),
    closedProfit: Number(closedProfit.toFixed(2)),
    openProfit: Number(openProfit.toFixed(2))
  };
}

  const { totalProfit, closedProfit, openProfit } = calculateTotalProfit(userData?.accountInfo);
  

  const handleSelect = (type) => {
    setActiveProfit(type);
  };

  const handleToggleChange = (value) => {
    setIsAutoTrackingEnabled(value);
  };

  const isValidNumber = (value) => typeof value === 'number' && !isNaN(value);

  const formatNumber = (value) => Number(value).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
    useGrouping: false
  });

  const balance = userData?.accountInfo?.balance ?? 0;

  const profitAmount = activeProfit === 'today'
    ? (isValidNumber(openProfit) ? formatNumber(openProfit) : 'NaN')
    : (isValidNumber(totalProfit) ? formatNumber(totalProfit) : 'NaN');

  const profitToday = (isValidNumber(openProfit) && balance > 0)
    ? (openProfit / (balance / 100)).toFixed(2)
    : 'NaN';

  const profitTotal = (isValidNumber(totalProfit) && balance > 0)
    ? (totalProfit / (balance / 100)).toFixed(2)
    : 'NaN';

  const positions = userData?.accountInfo?.positions_closed || [];
  const profits = positions.map(pos => parseFloat(pos.profit));

  // Коэффициент Шарпа
  const sharpeRatio = calculateSharpeRatio(profits);

  return (
    <div className={appliedStyles.container}>
      {isVisible ? <AutoTracking onToggleChange={handleToggleChange}/> : null}
      <div className={appliedStyles.columnContainer}>
        <div className={appliedStyles.rowContainer}>
          <div className={appliedStyles.header}>
            <h2 className={appliedStyles.tytle}>Депозит {real ? '(Основной)' : '(Демо)'}</h2>
            <h3 className={appliedStyles.inUse}>Задействовано: {marginUsedPercent}%</h3>
          </div>
          <div className={appliedStyles.depositInformation}>
            <h3 className={appliedStyles.depositCurrency}>{userData?.accountInfo?.currency ?? 'N/A'}</h3>
            <h3 className={appliedStyles.depositVolume}>{userData?.accountInfo?.equity ?? 'N/A'}</h3> 
          </div>

        </div>
        
        <div className={appliedStyles.rowContainer}>
          <div className={appliedStyles.profitInformation}>
            <div
              className={`${appliedStyles.profitToday} ${
                activeProfit === 'today' ? appliedStyles.active : appliedStyles.inactive
              }`}
              onClick={() => handleSelect('today')}
            >
              <span className={appliedStyles.profitTodayTitle}>Сегодня</span>
              <span className={appliedStyles.profitTodayValue}>{profitToday}%</span>
            </div>

            <div
              className={`${appliedStyles.profitTotal} ${
                activeProfit === 'total' ? appliedStyles.active : appliedStyles.inactive
              }`}
              onClick={() => handleSelect('total')}
            >
              <span className={appliedStyles.profitTodayTitle}>Всего</span>
              <span className={appliedStyles.profitTodayValue}>{profitTotal}%</span>
            </div>
          </div>
           <div className={appliedStyles.depositInformation}>
            {showDepositCurrency ? <h3 className={appliedStyles.depositCurrency}>{userData?.accountInfo?.currency ?? 'N/A'}</h3> : null}
            <div className={appliedStyles.profitАmount}>{profitAmount}</div>
          </div>  
        </div>
      </div>          
      {statistics ?       
      <div className={appliedStyles.statistics}>
        <Efficiency 
          title={'Количество трейдов'}
          /*view={'#1D1D1D'}*/
          value={Number(tradesNumber).toLocaleString('en-US', {
                    minimumFractionDigits: 0,
                    maximumFractionDigits: 0,
                    useGrouping: false // убираем разделитель тысяч
                  })}
        />
        <Efficiency 
          title={'Прибыль/убыток'}
          /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
          value={Number(totalProfit).toLocaleString('en-US', {
                    minimumFractionDigits: 2,
                    maximumFractionDigits: 2,
                    useGrouping: false // убираем разделитель тысяч
                  })}
        />
        <Efficiency 
          title={'Коэффициент Шарпа'}
          /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
          value={sharpeRatio.toFixed(2)}
        />
      </div> : null}

    </div>
  );
};