import { useState } from 'react'
import { EfficiencyTradesPage } from '../user/sections/components/Efficiency'
import { DropdownTabs } from '../user/sections/components/DropdownTabs'
import styles from './RewardCalculator.module.css'

export const RewardCalculator = () => {
  const [timeframeSelector, setTimeframeSelector] = useState('10 000 - 49 999');
  const [discountClientCommission, setdiscountClientCommission] = useState(10)
  const [yourReward, setyourReward] = useState(10)
  const [clientDeposit, setClientDeposit] = useState(10000)

  const options = [
  '10 000 - 49 999',
  '50 000 - 99 999',
  '100 000 - 249 999',
  '250 000 - 499 999',
  '500 000+'
];

const depositValues = [10000, 50000, 100000,250000, 500000]

const rewardValues = [10, 12, 15, 18, 20];
const discountValues = [10, 10, 10, 10, 10];            
  
const discountCommission = 3;

const formatNumber = new Intl.NumberFormat('ru-RU', {
  minimumFractionDigits: 0
});
console.log(depositValues)
const firstStep = Math.floor(clientDeposit * discountClientCommission / 100); 
const twoStep = Math.floor(firstStep * 30 / 100); 
const threeStep = Math.floor(twoStep * yourReward / 100); 

const handleSelectorChange = (value) => {
  const index = options.indexOf(value); // найдём индекс выбранного элемента

  if (index !== -1) {
    setTimeframeSelector(value);
    setdiscountClientCommission(discountValues[index]);
    setyourReward(rewardValues[index]);
    setClientDeposit(depositValues[index]);
    
  }
};


  return (
    <div className={styles.container}>
      <h2 className={styles.title}>Калькулятор вознаграждения по партнерской программе</h2>
      <div className={styles.calculator}>
        <h4 className={styles.subtitle}>Депозит приглашенного Вами клиента, USD </h4>
        <DropdownTabs
          indicator={false}
          title={''}
          options={options}
          onChange={handleSelectorChange}
        />
        <div className={styles.results}>
          <div className={styles.rounds}>
            <div className={styles.round}>
              <h4 className={styles.subtitleRound}>Скидка на комиссию для приглашенного Вами клиента,% </h4>
              <EfficiencyTradesPage 
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValueLabel={''}
                firstValue={discountCommission}
              />
            </div>
            <div className={styles.round}>
              <h4 className={styles.subtitleRound}>Скидка на Вашу комиссию,%</h4>
              <EfficiencyTradesPage 
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValueLabel={''}
                firstValue={discountClientCommission}
              />
            </div>  
            <div className={styles.round}>
              <h4 className={styles.subtitleRound}>Ваше вознаграждение,% </h4>
                <EfficiencyTradesPage 
                /*view={'linear-gradient(0deg, #20661C, #20661C)'}*/
                firstValueLabel={''}
                firstValue={yourReward}
              />
            </div>     

          </div>
          <div className={styles.calculationExample}>
            <h4 className={styles.subtitleExample}>Пример расчета суммы Вашего вознаграждения</h4>
            <div className={styles.report}>
              <span className={styles.itemReport}>
                {formatNumber.format(clientDeposit)}$ × {yourReward}% = {formatNumber.format(firstStep)}$
                <span className={styles.underline}></span>
              </span>
              <span className={styles.itemReport}>
                {formatNumber.format(firstStep)}$ × {30}% = {formatNumber.format(twoStep)}$
                <span className={styles.underline}></span>
              </span>
              <span className={styles.itemReport}>
                {formatNumber.format(twoStep)}$ × {yourReward}% = {formatNumber.format(threeStep)}$
                <span className={styles.underline}></span>
              </span>
              <span className={styles.itemReportTotal}>
                Итого: {formatNumber.format(threeStep)}$
              </span>
              
            </div>
          </div>
        </div>
      </div>
    </div>
  )
}
