import styles from "./TestBlock.module.css";


export const TestBlock = ({ accountData, timeframeSelector }) => {
  if (!accountData) {
    return <div className={styles.empty}>Нет данных по счёту</div>;
  }

  const opened = accountData?.data?.accountInfo?.positions_opened || [];
  const closed = accountData?.data?.accountInfo?.positions_closed || [];

  // Объединяем: открытые первыми, потом закрытые
  const allPositions = [
    ...opened.map((pos) => ({
      ...pos,
      status: "opened",
    })),
    ...closed.map((pos) => ({
      ...pos,
      status: "closed",
    })),
  ];

  // Для сортировки: открытые первыми, потом закрытые по времени закрытия (свежие сверху)
  allPositions.sort((a, b) => {
    if (a.status !== b.status) return a.status === "opened" ? -1 : 1;
    const aTime = a.status === "opened" ? a.time_open : a.time;
    const bTime = b.status === "opened" ? b.time_open : b.time;
    return Number(bTime) - Number(aTime);
  });

  // === ФИЛЬТРАЦИЯ ПО ТАЙМФРЕЙМУ ===
  const timeframeMap = {
    'День': 1,
    'Неделя': 7,
    'Месяц': 30,
    '6 Месяцев': 182,
    'Год': 365
  };
  const days = timeframeMap[timeframeSelector] || 365;
  const now = new Date();
  const fromDate = new Date(now.getTime() - days * 24 * 60 * 60 * 1000);

  const filteredPositions = allPositions.filter(pos => {
    const timestamp = pos.status === "opened" ? pos.time_open : pos.time;
    if (!timestamp) return false;
    const posDate = new Date(Number(timestamp) * 1000);
    return posDate >= fromDate;
  });

  // Итог по открытым
  const totalProfitOpened = filteredPositions
    .filter(pos => pos.status === "opened")
    .reduce((sum, pos) => sum + (Number(pos.profit) || 0), 0);

  // Итог по закрытым
  const totalProfitClosed = filteredPositions
    .filter(pos => pos.status === "closed")
    .reduce((sum, pos) => sum + (Number(pos.profit) || 0), 0);

  // Общая прибыль
  const totalProfitAll = totalProfitOpened + totalProfitClosed;

  // Функция для отображения типа сделки
  const getType = (type) => {
    if (type === 0 || type === "0") return "Buy";
    if (type === 1 || type === "1") return "Sell";
    return type;
  };

  // Функция для отображения кто открыл
  const getWho = (who) => {
    if (who === "manual") return "Вручную";
    if (who === "ea") return "ИИ ассистент";
    return who;
  };

  // Функция для подсветки строки
  const getRowClass = (status) => {
    if (status === "opened") return styles.openedRow;
    if (status === "closed") return styles.closedRow;
    return "";
  };

return (
  <div className={styles.container}>
    <h3>Все позиции</h3>
    {filteredPositions.length > 0 ? (
      <table className={styles.positionsTable}>
        <thead>
          <tr>
            {/*<th>Статус</th>*/}
            {/*<th>Тикет</th>*/}
            <th>Символ</th>
            <th>Тип</th>
            <th>Объём</th>
            {/*<th>Цена открытия</th>*/}
            {/*<th>Цена закрытия</th>*/}
            <th>SL</th>
            <th>TP</th>
            <th>Профит</th>
            {/*<th>Swap</th>*/}
            <th>Комиссия</th>
            {/*<th>Метод открытия</th>*/}
            {/*<th>Комментарий</th>*/}
            {/*<th>Время открытия</th>*/}
            <th>Время закрытия</th>
          </tr>
        </thead>
        <tbody>
          {filteredPositions.map((pos) => (
            <tr key={pos.ticket} className={getRowClass(pos.status)}>
               {/*<td data-label="Статус">
                {pos.status === "opened" ? (
                  <span className={styles.openedLabel}>Открыта</span>
                ) : (
                  <span className={styles.closedLabel}>Закрыта</span>
                )}
              </td>*/}
               {/*<td data-label="Тикет">{pos.ticket}</td>*/}
              <td data-label="Символ">{pos.symbol}</td>
              <td data-label="Тип">{getType(pos.type)}</td>
              <td data-label="Объём">{pos.volume}</td>
               {/*<td data-label="Цена открытия">{pos.price_open || pos.open_price}</td>*/}
               {/*<td data-label="Цена закрытия">{pos.close_price || (pos.status === "opened" ? "-" : "")}</td>*/}
              <td data-label="SL">{pos.sl}</td>
              <td data-label="TP">{pos.tp}</td>
              <td data-label="Профит"
                className={pos.profit < 0 ? styles.negative : styles.positive}
              >
                {pos.profit > 0 ? `+${pos.profit}` : pos.profit}
              </td>
               {/*<td data-label="Swap">{pos.swap}</td>*/}
              <td data-label="Комиссия">{pos.commission}</td>
               {/*<td data-label="Метод открытия">{getWho(pos.who)}</td>*/}
               {/*<td data-label="Комментарий">{pos.comment}</td>*/}
               {/*<td data-label="Время открытия">
                {pos.time_open
                  ? new Date(Number(pos.time_open) * 1000).toLocaleString()
                  : pos.open_price
                  ? "-"
                  : ""}
              </td>*/}
              <td data-label="Время закрытия">
                {pos.time
                  ? new Date(Number(pos.time) * 1000).toLocaleString()
                  : pos.close_price
                  ? "-"
                  : ""}
              </td>
            </tr>
          ))}
        </tbody>
 <tfoot>
  <tr>
    <td></td>
    <td colSpan={6} style={{ textAlign: "right", fontWeight: "bold" }}>
      Итого по открытым:
    </td>
    <td
      className={
        totalProfitOpened < 0 ? styles.negative : styles.positive
      }
      style={{ fontWeight: "bold" }}
    >
      {totalProfitOpened > 0
        ? `+${totalProfitOpened.toFixed(2)}`
        : totalProfitOpened.toFixed(2)}
    </td>

  </tr>
  <tr>
    <td></td>
    <td colSpan={6} style={{ textAlign: "right", fontWeight: "bold" }}>
      Итого по закрытым:
    </td>
    <td
      className={
        totalProfitClosed < 0 ? styles.negative : styles.positive
      }
      style={{ fontWeight: "bold" }}
    >
      {totalProfitClosed > 0
        ? `+${totalProfitClosed.toFixed(2)}`
        : totalProfitClosed.toFixed(2)}
    </td>
    
  </tr>
  <tr>
    <td></td>
    <td colSpan={6} style={{ textAlign: "right", fontWeight: "bold" }}>
      Общая прибыль:
    </td>
    <td
      className={
        totalProfitAll < 0 ? styles.negative : styles.positive
      }
      style={{ fontWeight: "bold" }}
    >
      {totalProfitAll > 0
        ? `+${totalProfitAll.toFixed(2)}`
        : totalProfitAll.toFixed(2)}
    </td>
    
  </tr>
</tfoot>
      </table>
    ) : (
      <div className={styles.empty}>Нет позиций</div>
    )}
  </div>
);
};